1	// Package metrics holds cumulative metric samples: their normalized content,
2	// batch ingestion with de-duplication, and the delta aggregation over aligned
3	// segments. Sample ids are independent of event ids.
4	package metrics
5	
6	import (
7		"errors"
8		"maps"
9		"math"
10		"sort"
11		"strconv"
12		"strings"
13		"sync"
14		"time"
15	
16		"github.com/cocosolocoder/signalroom/internal/events"
17	)
18	
19	// ValidationError reports that a sample failed normalization (or, during
20	// aggregation, that a query was invalid).
21	type ValidationError struct{ Reason string }
22	
23	func (e *ValidationError) Error() string { return e.Reason }
24	
25	// IsValidationError reports whether err is a metrics validation failure.
26	func IsValidationError(err error) bool {
27		var target *ValidationError
28		return errors.As(err, &target)
29	}
30	
31	// ConflictError reports an id clash with different content, a repeated id in
32	// one batch, or a series/time clash between different ids.
33	type ConflictError struct{ Reason string }
34	
35	func (e *ConflictError) Error() string { return e.Reason }
36	
37	// IsConflictError reports whether err is a metrics conflict.
38	func IsConflictError(err error) bool {
39		var target *ConflictError
40		return errors.As(err, &target)
41	}
42	
43	// Sample is one normalized cumulative counter reading. Labels carries the
44	// optional trimmed label set and is nil when the sample has none.
45	type Sample struct {
46		ID      string
47		Service string
48		Name    string
49		At      time.Time
50		Value   float64
51		Labels  map[string]string
52	}
53	
54	// Normalize applies the ingestion rules: trim surrounding whitespace from id,
55	// service, and metric name (their case is kept) and require each non-empty
56	// afterwards; require a non-zero instant; require a non-negative, finite
57	// value; and trim/validate labels with the same rules events use.
58	func Normalize(s Sample) (Sample, error) {
59		s.ID = strings.TrimSpace(s.ID)
60		s.Service = strings.TrimSpace(s.Service)
61		s.Name = strings.TrimSpace(s.Name)
62		if s.ID == "" || s.Service == "" || s.Name == "" || s.At.IsZero() {
63			return Sample{}, &ValidationError{Reason: "sample id, service, name, and timestamp are required"}
64		}
65		if !finiteNonNegative(s.Value) {
66			return Sample{}, &ValidationError{Reason: "value must be a non-negative, finite JSON number"}
67		}
68		labels, err := events.NormalizeLabels(s.Labels)
69		if err != nil {
70			return Sample{}, &ValidationError{Reason: err.Error()}
71		}
72		s.Labels = labels
73		return s, nil
74	}
75	
76	// finiteNonNegative rejects NaN, infinities (which JSON cannot carry anyway),
77	// and negative readings.
78	func finiteNonNegative(v float64) bool {
79		return !math.IsNaN(v) && !math.IsInf(v, 0) && v >= 0
80	}
81	
82	// seriesKey identifies one time series: a metric name within a service plus
83	// the complete label set. Names are compared case-sensitively after trimming.
84	type seriesKey struct {
85		service string
86		name    string
87		labels  string
88	}
89	
90	// pointKey identifies one absolute instant within a series. Unlike
91	// time.Time.UnixNano, which overflows for instants outside 1678–2262 and can
92	// alias two distant times, the (seconds, nanoseconds) pair is exact for every
93	// instant the RFC3339Nano entry points accept, and Unix seconds already
94	// canonicalize timezone offsets so equal instants share one key.
95	type pointKey struct {
96		sec  int64
97		nsec int32
98	}
99	
100	// pointKeyOf renders an instant as its absolute point identity.
101	func pointKeyOf(at time.Time) pointKey {
102		return pointKey{sec: at.Unix(), nsec: int32(at.Nanosecond())}
103	}
104	
105	// BeforeCommit persists a batch of brand-new samples. It runs while the store
106	// lock is held and before the batch becomes visible, so a successful return
107	// guarantees the batch is durable and committed atomically.
108	type BeforeCommit func(persisted []Sample) error
109	
110	// Store is a concurrency-safe set of metric samples grouped into series. It
111	// accepts whole batches and reports retries of already-stored samples.
112	type Store struct {
113		mu     sync.RWMutex
114		byID   map[string]Sample
115		series map[seriesKey]*seriesState
116	}
117	
118	// NewStore returns an empty store.
119	func NewStore() *Store {
120		return &Store{
121			byID:   make(map[string]Sample),
122			series: make(map[seriesKey]*seriesState),
123		}
124	}
125	
126	// IngestResult counts how a batch was applied: Created samples are new,
127	// Replayed samples matched an existing sample with the same id and content.
128	type IngestResult struct {
129		Created  int
130		Replayed int
131	}
132	
133	// Ingest normalizes and validates every sample first, then checks the whole
134	// batch against stored samples and itself. Validation failures produce a
135	// ValidationError; duplicate ids with differing content, a repeated id within
136	// the batch, or a (series, time) clash between different ids produce a
137	// ConflictError. Nothing is stored when an error is returned.
138	//
139	// New samples are passed to beforeCommit for durable storage; only after it
140	// succeeds does the batch become visible, so concurrent readers see either the
141	// complete batch or none of it, and concurrent batches serialize so the whole
142	// batch either commits or fails.
143	func (s *Store) Ingest(batch []Sample, beforeCommit BeforeCommit) (IngestResult, error) {
144		normalized := make([]Sample, len(batch))
145		for i, sample := range batch {
146			norm, err := Normalize(sample)
147			if err != nil {
148				return IngestResult{}, err
149			}
150			normalized[i] = norm
151		}
152	
153		s.mu.Lock()
154		defer s.mu.Unlock()
155	
156		pendingID := make(map[string]struct{}, len(normalized))
157		pendingPoint := make(map[seriesKey]map[pointKey]string, len(normalized))
158		var created []Sample
159		var result IngestResult
160		for _, sample := range normalized {
161			if _, repeated := pendingID[sample.ID]; repeated {
162				return IngestResult{}, &ConflictError{Reason: "sample id repeats within batch"}
163			}
164			pendingID[sample.ID] = struct{}{}
165	
166			key := keyFor(sample)
167			if existing, ok := s.byID[sample.ID]; ok {
168				if !sameContent(existing, sample) {
169					return IngestResult{}, &ConflictError{Reason: "sample id already exists with different content"}
170				}
171				// An id retry must never mask another id's point.
172				if owner := s.series[key].pointOwner(sample.At); owner != "" && owner != sample.ID {
173					return IngestResult{}, &ConflictError{
174						Reason: "sample collides with a different sample of the same series at the same time"}
175				}
176				result.Replayed++
177				continue
178			}
179	
180			// A brand-new id must not claim a (series, time) point already stored
181			// under another id.
182			if owner := s.series[key].pointOwner(sample.At); owner != "" {
183				return IngestResult{}, &ConflictError{
184					Reason: "sample collides with a different sample of the same series at the same time"}
185			}
186			// Nor one introduced earlier in this same batch.
187			if owners := pendingPoint[key]; owners != nil {
188				if owner, dup := owners[pointKeyOf(sample.At)]; dup && owner != sample.ID {
189					return IngestResult{}, &ConflictError{
190						Reason: "sample collides with a different sample of the same series at the same time"}
191				}
192			}
193			created = append(created, sample)
194			result.Created++
195			if pendingPoint[key] == nil {
196				pendingPoint[key] = make(map[pointKey]string)
197			}
198			pendingPoint[key][pointKeyOf(sample.At)] = sample.ID
199		}
200	
201		if len(created) > 0 {
202			if beforeCommit != nil {
203				if err := beforeCommit(created); err != nil {
204					return IngestResult{}, err
205				}
206			}
207			for _, sample := range created {
208				s.byID[sample.ID] = sample
209				key := keyFor(sample)
210				state := s.series[key]
211				if state == nil {
212					state = &seriesState{labels: sample.Labels}
213					s.series[key] = state
214				}
215				state.add(sample)
216			}
217		}
218		return result, nil
219	}
220	
221	// Load inserts samples recovered from durable storage during startup. Every
222	// sample must already be normalized; a contradictory record is reported as a
223	// conflict so the caller can fail rather than mutate data.
224	func (s *Store) Load(sample Sample) error {
225		if _, err := Normalize(sample); err != nil {
226			return err
227		}
228		s.mu.Lock()
229		defer s.mu.Unlock()
230		key := keyFor(sample)
231		if existing, ok := s.byID[sample.ID]; ok {
232			if !sameContent(existing, sample) {
233				return &ConflictError{Reason: "sample id already exists with different content"}
234			}
235			return nil
236		}
237		if owner := s.series[key].pointOwner(sample.At); owner != "" {
238			return &ConflictError{Reason: "sample collides with a different sample of the same series at the same time"}
239		}
240		s.byID[sample.ID] = sample
241		state := s.series[key]
242		if state == nil {
243			state = &seriesState{labels: sample.Labels}
244			s.series[key] = state
245		}
246		state.add(sample)
247		return nil
248	}
249	
250	// keyFor builds the identity of a series from a normalized sample.
251	func keyFor(sample Sample) seriesKey {
252		return seriesKey{service: sample.Service, name: sample.Name, labels: labelsKey(sample.Labels)}
253	}
254	
255	// labelsKey renders a label set as a collision-free canonical string so two
256	// maps with the same complete set share a series regardless of iteration
257	// order. Name and value are each length-prefixed, which keeps values
258	// containing '=' or ';' from ever aliasing another set.
259	func labelsKey(labels map[string]string) string {
260		if len(labels) == 0 {
261			return ""
262		}
263		keys := make([]string, 0, len(labels))
264		for name := range labels {
265			keys = append(keys, name)
266		}
267		sort.Strings(keys)
268		var b strings.Builder
269		for _, name := range keys {
270			value := labels[name]
271			b.WriteString(strconv.Itoa(len(name)))
272			b.WriteByte(':')
273			b.WriteString(name)
274			b.WriteByte(',')
275			b.WriteString(strconv.Itoa(len(value)))
276			b.WriteByte(':')
277			b.WriteString(value)
278			b.WriteByte(';')
279		}
280		return b.String()
281	}
282	
283	// seriesState is one sorted run of (time, value, id) points sharing one
284	// label set.
285	type seriesState struct {
286		labels map[string]string
287		points []point
288	}
289	
290	type point struct {
291		at    time.Time
292		value float64
293		id    string
294	}
295	
296	// add inserts one point keeping the run ordered by time. Points at the same
297	// instant for one series are rejected upstream.
298	func (st *seriesState) add(sample Sample) {
299		p := point{at: sample.At, value: sample.Value, id: sample.ID}
300		idx := sort.Search(len(st.points), func(i int) bool {
301			return st.points[i].at.After(p.at)
302		})
303		st.points = append(st.points, point{})
304		copy(st.points[idx+1:], st.points[idx:])
305		st.points[idx] = p
306	}
307	
308	// pointOwner returns the id of the sample at exactly at, or "" when the point
309	// is absent. A nil receiver reports no owner.
310	func (st *seriesState) pointOwner(at time.Time) string {
311		if st == nil {
312			return ""
313		}
314		idx := sort.Search(len(st.points), func(i int) bool {
315			return !st.points[i].at.Before(at)
316		})
317		if idx < len(st.points) && st.points[idx].at.Equal(at) {
318			return st.points[idx].id
319		}
320		return ""
321	}
322	
323	// sameContent compares two normalized samples on their absolute instant,
324	// value, and label set. Numeric equality makes 1 and 1.0 identical; map
325	// comparison makes label key order irrelevant.
326	func sameContent(a, b Sample) bool {
327		return a.ID == b.ID &&
328			a.Service == b.Service &&
329			a.Name == b.Name &&
330			a.At.Equal(b.At) &&
331			a.Value == b.Value &&
332			maps.Equal(a.Labels, b.Labels)
333	}
