50			count        int
51			delta        float64
52			since, until int64
53		}{
54			{2, 8, 10, 15}, // a@10 rises +5, b@13 resets to +3
55			{1, 1, 15, 20}, // c@16 rises +1
56		}
57		for i, w := range want {
