1	package httpapi
2	
3	import (
4		"bytes"
5		"errors"
6		"net/http"
7		"strconv"
8		"strings"
9		"time"
10	
11		"github.com/cocosolocoder/signalroom/internal/events"
12		"github.com/cocosolocoder/signalroom/internal/metrics"
13	)
14	
15	// MetricStorage durably persists a metric batch before it becomes visible and
16	// reports whether metric storage has failed.
17	type MetricStorage interface {
18		Append(batch []metrics.Sample) error
19		Poisoned() bool
20	}
21	
22	// allowedMetricsFields is the exact set of members a POST /metrics body may
23	// carry.
24	var allowedMetricsFields = map[string]struct{}{
25		"samples": {},
26	}
27	
28	type ingestMetricsResponse struct {
29		Created  int `json:"created"`
30		Replayed int `json:"replayed"`
31	}
32	
33	type aggregateSeriesDTO struct {
34		Service  string                `json:"service"`
35		Labels   map[string]string     `json:"labels,omitempty"`
36		Segments []aggregateSegmentDTO `json:"segments"`
37	}
38	
39	type aggregateSegmentDTO struct {
40		Since string  `json:"since"`
41		Until string  `json:"until"`
42		Count int     `json:"count"`
43		Delta float64 `json:"delta"`
44	}
45	
46	func (h *Handler) metricsRoot(w http.ResponseWriter, r *http.Request) {
47		if r.Method != http.MethodPost {
48			w.Header().Set("Allow", "POST")
49			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
50			return
51		}
52		h.postMetrics(w, r)
53	}
54	
55	func (h *Handler) metricsAggregate(w http.ResponseWriter, r *http.Request) {
56		if r.Method != http.MethodGet {
57			w.Header().Set("Allow", "GET")
58			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
59			return
60		}
61		h.getMetricsAggregate(w, r)
62	}
63	
64	func (h *Handler) metricsUnavailable(w http.ResponseWriter) bool {
65		if h.metricLogs == nil || h.metricLogs.Poisoned() {
66			writeError(w, http.StatusServiceUnavailable, "metric storage is unavailable; restart required")
67			return true
68		}
69		return false
70	}
71	
72	func (h *Handler) postMetrics(w http.ResponseWriter, r *http.Request) {
73		if h.metricsUnavailable(w) {
74			return
75		}
76	
77		body, err := readJSONObjectBody(w, r, allowedMetricsFields)
78		if err != nil {
79			writeError(w, http.StatusBadRequest, "invalid JSON body")
80			return
81		}
82		rawSamples, present := body["samples"]
83		trimmed := bytes.TrimSpace(rawSamples)
84		if !present || bytes.Equal(trimmed, []byte("null")) || bytes.Equal(trimmed, []byte("[]")) {
85			writeError(w, http.StatusBadRequest, "samples must be a non-empty array")
86			return
87		}
88	
89		batch, err := metrics.DecodeBatch(rawSamples)
90		if err != nil {
91			writeError(w, http.StatusBadRequest, "invalid samples array")
92			return
93		}
94		if len(batch) == 0 {
95			writeError(w, http.StatusBadRequest, "samples must not be empty")
96			return
97		}
98	
99		result, err := h.metrics.Ingest(batch, h.metricLogs.Append)
100		if err != nil {
101			switch {
102			case metrics.IsValidationError(err):
103				writeError(w, http.StatusBadRequest, err.Error())
104			case metrics.IsConflictError(err):
105				writeError(w, http.StatusConflict, err.Error())
106			default:
107				writeError(w, http.StatusServiceUnavailable, "metric storage is unavailable; restart required")
108			}
109			return
110		}
111	
112		writeJSON(w, http.StatusOK, ingestMetricsResponse{
113			Created: result.Created, Replayed: result.Replayed,
114		})
115	}
116	
117	func (h *Handler) getMetricsAggregate(w http.ResponseWriter, r *http.Request) {
118		if h.metricsUnavailable(w) {
119			return
120		}
121	
122		values := r.URL.Query()
123	
124		name, ok := singleValue(values, "name")
125		if !ok || strings.TrimSpace(name) == "" {
126			writeError(w, http.StatusBadRequest, "name is required and must be a single non-empty value")
127			return
128		}
129	
130		parseTime := func(param string) (time.Time, bool) {
131			raw, ok := singleValue(values, param)
132			if !ok || raw == "" {
133				writeError(w, http.StatusBadRequest, param+" is required and must be a single RFC3339Nano timestamp")
134				return time.Time{}, false
135			}
136			parsed, err := time.Parse(time.RFC3339Nano, raw)
137			if err != nil {
138				writeError(w, http.StatusBadRequest, param+" must be an RFC3339Nano timestamp")
139				return time.Time{}, false
140			}
141			return parsed, true
142		}
143		since, ok := parseTime("since")
144		if !ok {
145			return
146		}
147		until, ok := parseTime("until")
148		if !ok {
149			return
150		}
151		if !since.Before(until) {
152			writeError(w, http.StatusBadRequest, "since must be strictly before until")
153			return
154		}
155	
156		rawStep, ok := singleValue(values, "step")
157		if !ok || rawStep == "" {
158			writeError(w, http.StatusBadRequest, "step is required and must be a single integer number of seconds")
159			return
160		}
161		if !isDecimal(rawStep) {
162			writeError(w, http.StatusBadRequest, "step must be an integer from 1 to 86400 seconds")
163			return
164		}
165		stepSeconds, err := strconv.ParseInt(rawStep, 10, 64)
166		if err != nil || stepSeconds < minStepSeconds || stepSeconds > maxStepSeconds {
167			writeError(w, http.StatusBadRequest, "step must be an integer from 1 to 86400 seconds")
168			return
169		}
170	
171		// service is optional but, like the other parameters, may not repeat.
172		var service string
173		if rawServices, present := values["service"]; present {
174			if len(rawServices) != 1 {
175				writeError(w, http.StatusBadRequest, "service must be a single value")
176				return
177			}
