13		"github.com/cocosolocoder/signalroom/internal/events"
14		"github.com/cocosolocoder/signalroom/internal/metrics"
15	)
16	
17	type fakeMetricStorage struct {
18		mu       sync.Mutex
19		failNext bool
20		poisoned bool
21		batches  [][]metrics.Sample
22	}
23	
24	func (f *fakeMetricStorage) Append(batch []metrics.Sample) error {
25		f.mu.Lock()
26		defer f.mu.Unlock()
27		if f.failNext {
28			f.poisoned = true
29			f.failNext = false
30			return errors.New("simulated metric write failure")
31		}
32		f.batches = append(f.batches, append([]metrics.Sample(nil), batch...))
33		return nil
34	}
35	
36	func (f *fakeMetricStorage) Poisoned() bool {
37		f.mu.Lock()
38		defer f.mu.Unlock()
39		return f.poisoned
40	}
41	
42	func newMetricsServer(t *testing.T, store *metrics.Store, mstore *fakeMetricStorage) *httptest.Server {
43		t.Helper()
44		if store == nil {
45			store = metrics.NewStore()
46		}
47		if mstore == nil {
48			mstore = &fakeMetricStorage{}
49		}
50		tl := events.NewTimeline()
51		eventStore := &fakeStorage{cursorKey: []byte("test-cursor-key-0123456789ab")}
52		server := httptest.NewServer(NewHandler(tl, eventStore, eventStore, WithMetrics(store, mstore)))
53		t.Cleanup(server.Close)
54		return server
55	}
56	
57	func metricsDo(t *testing.T, server *httptest.Server, method, path, body string) (int, map[string]any) {
58		t.Helper()
59		var reader io.Reader
60		if body != "" {
61			reader = strings.NewReader(body)
62		}
63		req, err := http.NewRequest(method, server.URL+path, reader)
64		if err != nil {
65			t.Fatal(err)
66		}
67		if body != "" {
68			req.Header.Set("Content-Type", "application/json")
69		}
70		resp, err := http.DefaultClient.Do(req)
71		if err != nil {
72			t.Fatal(err)
73		}
74		defer resp.Body.Close()
75		raw, err := io.ReadAll(resp.Body)
76		if err != nil {
77			t.Fatal(err)
78		}
79		var out map[string]any
80		if err := json.Unmarshal(raw, &out); err != nil {
81			t.Fatalf("decode %q (%d): %v", raw, resp.StatusCode, err)
82		}
83		return resp.StatusCode, out
84	}
85	
86	func postSamples(t *testing.T, server *httptest.Server, body string) map[string]any {
87		t.Helper()
88		status, out := metricsDo(t, server, http.MethodPost, "/metrics", body)
89		if status >= 400 {
90			t.Fatalf("POST /metrics %d: %v", status, out)
91		}
92		return out
93	}
94	
95	func TestPostMetricsCreatedAndReplayed(t *testing.T) {
96		server := newMetricsServer(t, nil, nil)
97		body := `{"samples":[
98			{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1},
99			{"id":"s2","service":"gw","name":"requests","at":"2026-10-01T10:00:01Z","value":2,"labels":{"env":"prod"}}
100		]}`
101		out := postSamples(t, server, body)
102		if int(number(out["created"])) != 2 || int(number(out["replayed"])) != 0 {
103			t.Fatalf("initial: %v", out)
104		}
105	
106		// Retry with 1.0 numeric equivalence.
107		retry := `{"samples":[
108			{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1.0},
109			{"id":"s2","service":"gw","name":"requests","at":"2026-10-01T18:00:01+08:00","value":2,"labels":{"env":"prod"}}
110		]}`
111		out = postSamples(t, server, retry)
112		if int(number(out["created"])) != 0 || int(number(out["replayed"])) != 2 {
113			t.Fatalf("retry: %v", out)
114		}
115	}
116	
117	func TestPostMetricsValidationAndConflict(t *testing.T) {
118		server := newMetricsServer(t, nil, nil)
119		postSamples(t, server, `{"samples":[{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`)
120	
121		cases := []struct {
122			name   string
123			body   string
124			status int
125		}{
126			{"empty array", `{"samples":[]}`, http.StatusBadRequest},
127			{"missing samples", `{}`, http.StatusBadRequest},
128			{"unknown field", `{"samples":[{"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}],"x":1}`, http.StatusBadRequest},
129			{"blank id", `{"samples":[{"id":"  ","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`, http.StatusBadRequest},
130			{"negative value", `{"samples":[{"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":-1}]}`, http.StatusBadRequest},
131			{"string value", `{"samples":[{"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":"1"}]}`, http.StatusBadRequest},
132			{"bad time", `{"samples":[{"id":"s9","service":"gw","name":"requests","at":"nope","value":1}]}`, http.StatusBadRequest},
133			{"duplicate json field", `{"samples":[{"id":"s9","id":"s10","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`, http.StatusBadRequest},
134			{"changed content", `{"samples":[{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":5}]}`, http.StatusConflict},
135			{"series time clash", `{"samples":[{"id":"s2","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`, http.StatusConflict},
136			{"in-batch dup id", `{"samples":[{"id":"d","service":"gw","name":"requests","at":"2026-10-01T10:00:01Z","value":1},{"id":"d","service":"gw","name":"requests","at":"2026-10-01T10:00:02Z","value":2}]}`, http.StatusConflict},
137		}
138		for _, tc := range cases {
139			status, out := metricsDo(t, server, http.MethodPost, "/metrics", tc.body)
140			if status != tc.status {
141				t.Fatalf("%s: want %d, got %d (%v)", tc.name, tc.status, status, out)
142			}
143			if out["error"] == "" {
144				t.Fatalf("%s: non-empty error required, got %v", tc.name, out)
145			}
146		}
147	}
148	
149	func TestPostMetricsValidationPrecedesConflict(t *testing.T) {
150		server := newMetricsServer(t, nil, nil)
151		postSamples(t, server, `{"samples":[{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`)
152		status, _ := metricsDo(t, server, http.MethodPost, "/metrics", `{"samples":[
153			{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":5},
154			{"id":" ","service":"gw","name":"requests","at":"2026-10-01T10:00:01Z","value":1}
155		]}`)
156		if status != http.StatusBadRequest {
157			t.Fatalf("validation must precede conflict, got %d", status)
158		}
159	}
160	
